import { calculateInvoiceTotal, validateInvoice, type Invoice } from './billing.js';
import { sessionIsValid, type Session } from './session.js';

// Submit an order only after session authorization and invoice validation.
export function submitOrder(invoice: Invoice, session: Session, now: number): number {
  if (!sessionIsValid(session, now)) throw new Err

export function validateInvoice(invoice: Invoice): boolean {
  return invoice.subtotal >= 0 && invoice.taxRate >= 0 && invoice.taxRate <= 1;
}

export interface Session { expiresAt: number; userId: string; }

// An expired session cannot authorize a request.
export function sessionIsValid(session: Session, now: number): boolean {
  return session.expiresAt > now && session.userId.length > 0;
}

export function invoiceRoundingTest(): void {
  const total = calculateInvoiceTotal({ subtotal: 12.34, taxRate: 0.21 });
  if (total !== 14.93) throw new Error('Invoice rounding regression');
}

// Cache expiration is independent of login session expiration.
export function cacheEntryFresh(writtenAt: number, ttlMs: number, now: number): boolean {
  return writtenAt + ttlMs > now;
}

